window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ac8881e9c7328ae0"]={"versions": [{"id": "FIG-ac8881e9c7328ae0", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P22Protect</code> innerhalb der AUTOSAR E2E-Bibliothek (Profile 22, End-to-End Communication Protection).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion / Startknoten: <code>E2E_P22Protect(Config, State, Data, Length)</code></li>\n<li>Untergeordnete Aktivitätsstufen / Sub-Aktivitäten (mit Symbol für Sub-Aktivitäten):</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li>Guard-Bedingung: <code>[wrong input]</code> am rechten Fehlerpfad</li>\n<li>Endknoten / Rückgabewerte (Aktivitätsendknoten):</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (linker Zweig)</li>\n<li><code>return E2E_E_OK</code> (mittlerer Hauptzweig)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (rechter Zweig)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start der Funktion über den Initialknoten <code>E2E_P22Protect(Config, State, Data, Length)</code>.</li>\n<li>Ausführung der Sub-Aktivität <code>Verify inputs of the protect function</code>.</li>\n<li>Bedingte Verzweigung nach der Eingangsprüfung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Null-Zeiger-Fehler: Übergang zum linken Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei fehlerhaften Eingabeparametern (<code>[wrong input]</code>): Übergang zum rechten Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n<li>Bei erfolgreicher Prüfung: Fortführung im linearen Hauptpfad.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Hauptpfad:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Write Counter</code>: Schreibt den aktuellen Zählerstand in die Nutzdaten.</li>\n<li><code>Compute CRC</code>: Berechnet die CRC-Prüfsumme über den festgelegten Datenbereich.</li>\n<li><code>Write CRC</code>: Schreibt den berechneten CRC-Wert in das Datenfeld.</li>\n<li><code>Increment Counter</code>: Inkrementiert den Zähler im Zustandsüberwachungsobjekt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Erfolgreicher Abschluss im mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktion definiert das normative Berechnungs- und Schutzprotokoll für Profile 22. Entwickler müssen sicherstellen, dass bei der Initialausführung der aktuelle Zählerstand in die Daten geschrieben und die CRC berechnet wird, bevor der Zähler für die nachfolgende Übertragung inkrementiert wird. Fehlerhafte Parameter oder Nullzeiger müssen vor Beginn der Puffer- und Zustandsmanipulation abgefangen und mit den jeweiligen spezifischen Fehlercodes quittiert werden.</p>"}, {"id": "FIG-89445dad8e7e60ea", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P22Protect</code> innerhalb der AUTOSAR E2E-Bibliothek (Profile 22, End-to-End Communication Protection).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion / Startknoten: <code>E2E_P22Protect(Config, State, Data, Length)</code></li>\n<li>Untergeordnete Aktivitätsstufen / Sub-Aktivitäten:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Increment Counter</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li>Guard-Bedingungen an <code>Verify inputs of the protect function</code>:</li>\n<li><code>[null input]</code> (linker Fehlerpfad)</li>\n<li><code>[input ok]</code> (mittlerer Hauptpfad)</li>\n<li><code>[wrong input]</code> (rechter Fehlerpfad)</li>\n<li>Endknoten / Rückgabewerte:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (linker Zweig)</li>\n<li><code>return E2E_E_OK</code> (mittlerer Hauptzweig)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (rechter Zweig)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start der Funktion über den Initialknoten <code>E2E_P22Protect(Config, State, Data, Length)</code>.</li>\n<li>Ausführung der Sub-Aktivität <code>Verify inputs of the protect function</code>.</li>\n<li>Bedingte Verzweigung anhand der Guards:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Direkter Übergang zum linken Endknoten mit <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li><code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten mit <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n<li><code>[input ok]</code>: Fortsetzung im geschützten Hauptpfad.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Hauptpfad:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Increment Counter</code>: Inkrementiert den Zähler vor der Pufferbefüllung.</li>\n<li><code>Write Counter</code>: Schreibt den neu inkrementierten Zählerwert in die Daten.</li>\n<li><code>Compute CRC</code>: Führt die CRC-Berechnung über Nutzdaten und Zähler durch.</li>\n<li><code>Write CRC</code>: Schreibt die berechnete CRC in das Datenfeld.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Abschluss im mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensvorschrift für Profile 22 Protect: Der Counter muss vor dem Schreiben in den Datenpuffer inkrementiert werden (<code>Increment Counter</code> vor <code>Write Counter</code>), sodass der inkrementierte Zählerwert gesendet und in die CRC-Berechnung einbezogen wird. Eingangsparameter werden lückenlos über <code>[null input]</code>, <code>[wrong input]</code> und <code>[input ok]</code> abgeprüft, bevor der interne State modifiziert wird.</p>"}, {"id": "FIG-06f4ad496366714c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P22Protect</code> innerhalb der AUTOSAR E2E-Bibliothek (Profile 22, End-to-End Communication Protection).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion / Startknoten: <code>E2E_P22Protect(Config, State, Data, Length)</code></li>\n<li>Untergeordnete Aktivitätsstufen / Sub-Aktivitäten:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Increment Counter</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li>Guard-Bedingungen an <code>Verify inputs of the protect function</code>:</li>\n<li><code>[null input]</code> (linker Fehlerpfad)</li>\n<li><code>[input ok]</code> (mittlerer Hauptpfad)</li>\n<li><code>[wrong input]</code> (rechter Fehlerpfad)</li>\n<li>Endknoten / Rückgabewerte:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (linker Zweig)</li>\n<li><code>return E2E_E_OK</code> (mittlerer Hauptzweig)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (rechter Zweig)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start der Funktion über den Initialknoten <code>E2E_P22Protect(Config, State, Data, Length)</code>.</li>\n<li>Ausführung der Sub-Aktivität <code>Verify inputs of the protect function</code>.</li>\n<li>Bedingte Verzweigung anhand der Guards:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Direkter Übergang zum linken Endknoten mit <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li><code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten mit <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n<li><code>[input ok]</code>: Fortsetzung im geschützten Hauptpfad.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Hauptpfad:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Increment Counter</code>: Inkrementiert den Zähler vor der Pufferbefüllung.</li>\n<li><code>Write Counter</code>: Schreibt den neu inkrementierten Zählerwert in die Daten.</li>\n<li><code>Compute CRC</code>: Führt die CRC-Berechnung über Nutzdaten und Zähler durch.</li>\n<li><code>Write CRC</code>: Schreibt die berechnete CRC in das Datenfeld.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Abschluss im mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensvorschrift für Profile 22 Protect: Der Counter muss vor dem Schreiben in den Datenpuffer inkrementiert werden (<code>Increment Counter</code> vor <code>Write Counter</code>), sodass der inkrementierte Zählerwert gesendet und in die CRC-Berechnung einbezogen wird. Eingangsparameter werden lückenlos über <code>[null input]</code>, <code>[wrong input]</code> und <code>[input ok]</code> abgeprüft, bevor der interne State modifiziert wird.</p>"}, {"id": "FIG-18b390b76ae4f351", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P22Protect</code> innerhalb der AUTOSAR E2E-Bibliothek (Profile 22, End-to-End Communication Protection).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion / Startknoten: <code>E2E_P22Protect(Config, State, Data, Length)</code></li>\n<li>Untergeordnete Aktivitätsstufen / Sub-Aktivitäten:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Increment Counter</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li>Guard-Bedingungen an <code>Verify inputs of the protect function</code>:</li>\n<li><code>[null input]</code> (linker Fehlerpfad)</li>\n<li><code>[input ok]</code> (mittlerer Hauptpfad)</li>\n<li><code>[wrong input]</code> (rechter Fehlerpfad)</li>\n<li>Endknoten / Rückgabewerte:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (linker Zweig)</li>\n<li><code>return E2E_E_OK</code> (mittlerer Hauptzweig)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (rechter Zweig)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start der Funktion über den Initialknoten <code>E2E_P22Protect(Config, State, Data, Length)</code>.</li>\n<li>Ausführung der Sub-Aktivität <code>Verify inputs of the protect function</code>.</li>\n<li>Bedingte Verzweigung anhand der Guards:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Direkter Übergang zum linken Endknoten mit <code>return E2E_E_INPUTERR_NULL</code>.</li>\n<li><code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten mit <code>return E2E_E_INPUTERR_WRONG</code>.</li>\n<li><code>[input ok]</code>: Fortsetzung im geschützten Hauptpfad.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Hauptpfad:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Increment Counter</code>: Inkrementiert den Zähler vor der Pufferbefüllung.</li>\n<li><code>Write Counter</code>: Schreibt den neu inkrementierten Zählerwert in die Daten.</li>\n<li><code>Compute CRC</code>: Führt die CRC-Berechnung über Nutzdaten und Zähler durch.</li>\n<li><code>Write CRC</code>: Schreibt die berechnete CRC in das Datenfeld.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Abschluss im mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensvorschrift für Profile 22 Protect: Der Counter muss vor dem Schreiben in den Datenpuffer inkrementiert werden (<code>Increment Counter</code> vor <code>Write Counter</code>), sodass der inkrementierte Zählerwert gesendet und in die CRC-Berechnung einbezogen wird. Eingangsparameter werden lückenlos über <code>[null input]</code>, <code>[wrong input]</code> und <code>[input ok]</code> abgeprüft, bevor der interne State modifiziert wird.</p>"}], "trans": [{"from": "FIG-ac8881e9c7328ae0", "to": "FIG-89445dad8e7e60ea", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Schrittreihenfolge im Hauptpfad: „Increment Counter“ wird vor „Write Counter“ vorgezogen (vormals am Ende der Kette nach „Write CRC“).</li>\n<li>Verzweigungsbeschriftungen an „Verify inputs of the protect function“: Guards <code>[null input]</code> (linker Zweig) und <code>[input ok]</code> (mittlerer Zweig) explizit modelliert.</li>\n<li>Schrittkette nach Eingangsprüfung: Der Pfad <code>[input ok]</code> führt nun direkt auf „Increment Counter“ statt zuvor auf „Write Counter“.</li>\n</ul>"}, {"from": "FIG-89445dad8e7e60ea", "to": "FIG-06f4ad496366714c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-06f4ad496366714c", "to": "FIG-18b390b76ae4f351", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
